# A reply and its participant's answer are saved within a moment of each other.
MATCH_SECONDS = 10


def name_past_replies(apps, schema_editor):
    """Give each past invitee reply its person: the participant of that meeting who answered the same way closest
    in time (within a few seconds). Replies with no such match stay as they were."""
    MeetingResponse = apps.get_model('project_manager_agent', 'MeetingResponse')
    MeetingParticipant = apps.get_model('project_manager_agent', 'MeetingParticipant')
    replies = MeetingResponse.objects.filter(responded_by='invitee', responder__isnull=True).exclude(action='proposed')
    for reply in replies.iterator():
        best, gap = None, None
        for p in MeetingParticipant.objects.filter(meeting_id=reply.meeting_id, responded_at__isnull=False):
            seconds = abs((p.responded_at - reply.created_at).total_seconds())
            if seconds <= MATCH_SECONDS and (gap is None or seconds < gap):
                best, gap = p, seconds
        if best is not None:
            MeetingResponse.objects.filter(pk=reply.pk).update(responder_id=best.user_id)


